<?php require 'includes/header.php';require 'config/db.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$sid=(int)$_POST['student_id'];$date=$_POST['attendance_date'];$status=$_POST['status'];$q=$conn->prepare("INSERT INTO attendance(student_id,attendance_date,status) VALUES(?,?,?)");$q->bind_param('iss',$sid,$date,$status);$q->execute();header('Location:attendance.php');exit;}
$students=$conn->query("SELECT id,student_id,first_name,last_name FROM students ORDER BY first_name");$rows=$conn->query("SELECT a.*,s.student_id,s.first_name,s.last_name FROM attendance a JOIN students s ON s.id=a.student_id ORDER BY a.id DESC LIMIT 100");?>
<div class="d-flex justify-content-between mb-3"><h3>Attendance</h3><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#add">+ Mark Attendance</button></div>
<div class="card p-3"><table class="table"><tr><th>Date</th><th>Student</th><th>Status</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=$r['attendance_date']?></td><td><?=$r['student_id'].' - '.$r['first_name'].' '.$r['last_name']?></td><td><?=$r['status']?></td></tr><?php endwhile;?></table></div>
<div class="modal fade" id="add"><div class="modal-dialog"><div class="modal-content"><form method="post"><div class="modal-header"><h5>Mark Attendance</h5></div><div class="modal-body"><select name="student_id" class="form-select mb-2" required><option value="">Student</option><?php while($s=$students->fetch_assoc()):?><option value="<?=$s['id']?>"><?=$s['student_id'].' - '.$s['first_name'].' '.$s['last_name']?></option><?php endwhile;?></select><input type="date" name="attendance_date" class="form-control mb-2" value="<?=date('Y-m-d')?>" required><select name="status" class="form-select"><option>Present</option><option>Absent</option><option>Late</option></select></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div></div><?php require 'includes/footer.php'; ?>